---@class BattleSelectionTogNode
---@field ImgActivity                   	UnityEngine.RectTransform
---@field ImgIcon                       	Engine.UI.ImageAlterable
---@field TxtNum1                       	UnityEngine.RectTransform
---@field TxtTitle                      	UnityEngine.RectTransform
---@field Text                          	UnityEngine.RectTransform
---@field Lock                          	UnityEngine.RectTransform
---@field TxtTime                       	UnityEngine.RectTransform
---@field CurrentItem                   	UnityEngine.RectTransform
---@field Group2                        	UnityEngine.RectTransform
---@field Group1                        	UnityEngine.RectTransform
---@field TxtState                      	UnityEngine.RectTransform
---@field TxtName                       	UnityEngine.RectTransform
---@field RawImage                      	UnityEngine.RectTransform

local BattleSelectionTogNode = Class('BattleSelectionTogNode')

function BattleSelectionTogNode:__init()
    self._vo = nil
    self._clickCb = nil
    self._data = nil
end

function BattleSelectionTogNode:__delete()
    self._vo = nil
    self._clickCb = nil
    self._data = nil
end

function BattleSelectionTogNode:Awake()
    self.EventActionTimeDown = Events.AddListener(Constants.EventNames.ActionTimeDown, Bind(self, self.OnActionTimeDown))
    SetButtonAction(self.BtnBg, Bind(self, self.OnClick))
end

function BattleSelectionTogNode:Refresh(vo, data, clickCb)
    CfUtils.FillText(self.TxtTime, "")
    if not vo then
        return
    end
    self._vo = vo
    self._data = data
    self._clickCb = clickCb
    self:FillSelf()
end

function BattleSelectionTogNode:FillSelf()
    KTool.SetActive(self.Group1, false)
    KTool.SetActive(self.Group2, false)
    KTool.SetActive(self.ImgIcon, false)
    CfUtils.FillText(self.Text, "")
    self:FillCommon()

    GameUtils.RefeshSystemToggleId(self.BtnBg, self._vo.id)
    local isUnlcok = GameUtils.IsUnlockedBySystemTogId(self._vo.id)
    KTool.SetActive(self.Lock, not isUnlcok)

    --解锁
    if isUnlcok then
        self:FillTime()
        self:FillSpecial()
        self:InitRedPoint()
    else
        CfUtils.FillText(self.Text, GameUtils.GetUnlockDescrBySystemTogId(self._vo.id))
        KTool.SetActive(self.ImgActivity, false)
    end
end

--通用部分
function BattleSelectionTogNode:FillCommon()
    CfUtils.FillText(self.TxtName, self._vo.realRame)
    CfUtils.FillText(self.TxtState, self._vo.note)
    CfUtils.FillImage(self.RawImage, self._vo.actionIcon, false, Constants.ResPoolName.BattleSelectionTogNode, 1)
end

--绘制时间
function BattleSelectionTogNode:FillTime()
    local timeStr = ""
    local isShowActive = false

    local actionData = self._data
    if actionData then
        if checkNumber(self._vo.id) == Constants.SystemToggleIds.Id8 then       --迷宫
            if checkNumber(actionData.remainTime) > 0 then
                timeStr = CfUtils.GetTimeHMS5(actionData.remainTime)
            end     
        elseif checkNumber(self._vo.id) == Constants.SystemToggleIds.Id14 then   --世界boss
            local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.WorldBossComponent)
            local remainTime = comp:GetRemainTime()
            local durTime = comp:GetBossDurationTime()
            if checkNumber(remainTime) > 0 then
                timeStr = CfUtils.GetTimeHMS5(remainTime)
            else 
                timeStr = CfUtils.GetTimeHMS5(checkNumber(durTime) - math.abs(remainTime))
            end   
        elseif checkNumber(self._vo.id) == Constants.SystemToggleIds.Id9 then    --风暴挑战
            local playerComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
            timeStr = CfUtils.GetTimeHMS5(playerComponent.playerDojo.trialRemainTime)   
            isShowActive = false --(playerComponent.playerDojo.trialRemainTime > 0)
        elseif checkNumber(self._vo.id) == Constants.SystemToggleIds.Id22 then   --天赋
            local closeTime = checkNumber(actionData.closeTime)
            isShowActive = (closeTime > 0)
            local cycleTimeLeft = checkNumber(actionData.cycleTimeLeft)
            timeStr = CfUtils.GetTimeHMS5(cycleTimeLeft)
        elseif checkNumber(self._vo.id) == Constants.SystemToggleIds.Id20 then   --定向作战
            local questRemainTime = checkNumber(actionData.questRemainTime)
            timeStr = CfUtils.GetTimeHMS5(questRemainTime)
        elseif checkNumber(self._vo.id) == Constants.SystemToggleIds.Id3 then   --日常
            local closeTime = checkNumber(actionData.closeTime)
            KTool.SetActive(self.ImgActivity, closeTime > 0)
            timeStr = CfUtils.GetTimeHMS5(closeTime)
        elseif checkNumber(self._vo.id) == Constants.SystemToggleIds.Id16 then   --巅峰竞技
            ---@type PVPArenaEntryDojo
            local entryDojo = actionData
            --isShowActive = checkNumber(entryDojo.seasonStatus) ~= Constants.PVPArenaSeasonStatus.Closed
            timeStr = CfUtils.GetTimeHMS5(entryDojo.nextStageLeftSeconds)
        end
    end

    if self._vo.time == 0 then
        timeStr = self._vo.timeTxt
    end

    KTool.SetActive(self.ImgActivity, isShowActive)
    CfUtils.FillText(self.TxtTime, timeStr)
end

--特殊的一些
function BattleSelectionTogNode:FillSpecial()
    local actionData = self._data

    KTool.SetActive(self.Group2, false)
    KTool.SetActive(self.Group1, false)
    KTool.SetActive(self.ImgActivity, false)
    local redPointGo = self.controller.gameObject.transform:Find("redPoint")
    if redPointGo then
        KTool.SetActive(redPointGo, false)
    end

    if checkNumber(self._vo.id) == Constants.SystemToggleIds.Id8 then       --迷宫
        if actionData then
            if true == true then
                KTool.SetActive(self.Group2, true)
            else
                KTool.SetActive(self.Group1, true)
                local curFloor = checkNumber(actionData.passed) 
                CfUtils.FillText(self.TxtNum1, string.format("%d<size=30>/%d</size>", curFloor, checkNumber(actionData.joined)))
                CfUtils.FillText(self.TxtTitle, localize("当前进度"))
            end
        end
    elseif checkNumber(self._vo.id) == Constants.SystemToggleIds.Id14 then   --世界boss
        if actionData then
            if checkNumber(actionData.worldBossCurrentRanking) > 0 then
                KTool.SetActive(self.Group1, true)
                CfUtils.FillText(self.TxtNum1, checkNumber(actionData.worldBossCurrentRanking))
                CfUtils.FillText(self.TxtTitle, localize("排名"))
            else
                KTool.SetActive(self.Group2, true)
            end
        end
    elseif checkNumber(self._vo.id) == Constants.SystemToggleIds.Id15 then   --爬塔
        if actionData then
            local towerQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TowerQuestComponent)
            local lastId = checkNumber(towerQuestComponent:GetCurQuestId())
            local vo
            if checkNumber(actionData) == 0 then
                vo = QuestConfMgr:GetInstance():GetFirstTowerQuestVo()
            else
                local nextId = QuestConfMgr:GetInstance():GetNextTowerQuestId(actionData)
                --为0为关底
                if checkNumber(nextId) ~= 0 then
                    vo = QuestConfMgr:GetInstance():GetQuestVoById(nextId)
                else
                    vo = QuestConfMgr:GetInstance():GetQuestVoById(actionData)
                end
            end

            if vo then
                KTool.SetActive(self.Group1, true)
                CfUtils.FillText(self.TxtNum1, vo.level)
                CfUtils.FillText(self.TxtTitle, localize("当前层数"))
            else
                KTool.SetActive(self.Group2, true)
            end
        end
    elseif checkNumber(self._vo.id) == Constants.SystemToggleIds.Id9 then    --风暴挑战
        if actionData then
            if checkNumber(actionData.rank) > 0 then
                KTool.SetActive(self.Group1, true)
                CfUtils.FillText(self.TxtTitle, localize("排名"))
                CfUtils.FillText(self.TxtNum1, actionData.rank)
            else
                KTool.SetActive(self.Group2, true)
            end
        end
    elseif checkNumber(self._vo.id) == Constants.SystemToggleIds.Id22 then    --风暴挑战
        KTool.SetActive(self.Group2, true)
    elseif checkNumber(self._vo.id) == Constants.SystemToggleIds.Id3 then   
        KTool.SetActive(self.Group2, true)
    elseif checkNumber(self._vo.id) == Constants.SystemToggleIds.Id10 then   
        KTool.SetActive(self.Group2, true)
    elseif checkNumber(self._vo.id) == Constants.SystemToggleIds.Id20 then   
        KTool.SetActive(self.Group2, true)
    elseif checkNumber(self._vo.id) == Constants.SystemToggleIds.Id16 then   --巅峰竞技
        KTool.SetActive(self.Group2, true)
    end

    local status, desc = self:GetActiveStatusDesc()
    CfUtils.SetUISwitchImage(self.ImgActivity, status)
    CfUtils.FillText(self.ImgActivity.transform:Find("Text"), desc)
end

function BattleSelectionTogNode:GetActiveStatusDesc()
    if checkNumber(self._vo.id) == Constants.SystemToggleIds.Id14 then
        return 1, localize("活动中")
    elseif checkNumber(self._vo.id) == Constants.SystemToggleIds.Id9 then
        return 2, localize("推选中")
    elseif checkNumber(self._vo.id) == Constants.SystemToggleIds.Id16 then     --风暴巅峰
        return 1, localize("竞赛中")
    end
    return 1, localize("活动中")
end

function BattleSelectionTogNode:InitRedPoint()
    local redPointGo
    if checkNumber(self._vo.id) == Constants.SystemToggleIds.Id9 then    --风暴挑战
        redPointGo = GameUtils.BindRedPoint(Constants.RedPointConst.TrailQuest, self.controller.gameObject, true, Vector2(4, -6))
    end
end

--点击回调
function BattleSelectionTogNode:OnClick()
    local isUnlcok = GameUtils.IsUnlockedBySystemTogId(self._vo.id)
    if not isUnlcok then
        GameUtils.Toast(GameUtils.GetUnlockDescrBySystemTogId(self._vo.id))
        return
    end

    if self._clickCb then
        self._clickCb()
    end
end

function BattleSelectionTogNode:OnActionTimeDown()
    if self._vo then
        local isUnlcok = GameUtils.IsUnlockedBySystemTogId(self._vo.id)
        if isUnlcok then
            self:FillTime()
        end
    end
end

function BattleSelectionTogNode:OnDestroy()
    if not isNull(self) then
        Events.RemoveListener(Constants.EventNames.ActionTimeDown, self.EventActionTimeDown)
    end

    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return BattleSelectionTogNode
